  "sup-as1":{short:"Périmètres réglementaires de protection des eaux",what:"La servitude AS1 protège les captages d’eau destinée à la consommation humaine et certaines ressources minérales.",read:"Les périmètres peuvent imposer des interdictions ou prescriptions d’usage. La fiche officielle est référencée même lorsque sa géométrie n’est pas directement réutilisable."},
  "sup-a5":{short:"Servitudes liées aux canalisations publiques",what:"La servitude A5 concerne certaines canalisations publiques d’eau potable et d’assainissement.",read:"Elle peut encadrer l’accès, l’entretien et les constructions à proximité des ouvrages ; la source de référence est le Géoportail de l’urbanisme."},
  "assain-prix":{short:"Tarif de collecte et traitement des eaux usées",what:"Ce jeu décrit le prix du service d’assainissement collectif pour l’usager.",read:"Il complète le prix de l’eau potable. La ressource cartographique est conservée au catalogue même lorsque son téléchargement est indisponible."},
